package ru.yandex.practicum.catsgram.controller;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import ru.yandex.practicum.catsgram.model.Post;import ru.yandex.practicum.catsgram.service.PostService;import java.util.*;@RestController@RequestMapping("/posts")@RequiredArgsConstructorpublic class PostController {    private final PostService postService;    @GetMapping    public Collection<Post> findAll(@RequestParam(defaultValue = "0") int from,                                    @RequestParam(defaultValue = "10") int size,                                    @RequestParam(defaultValue = "desc") String sort) {        return postService.findAll(size, sort, from);    }    @GetMapping("/{id}")    public Post findById(@PathVariable long id) {        return postService.findById(id);    }    @PostMapping    @ResponseStatus(HttpStatus.CREATED)    public Post create(@RequestBody Post post) {        return postService.create(post);    }    @PutMapping    public Post update(@RequestBody Post newPost) {        return postService.update(newPost);    }}